import{_ as i,c as l,o as a,ae as s}from"./chunks/framework.BbFa6TS3.js";const E=JSON.parse('{"title":"实时数据传输","description":"","frontmatter":{},"headers":[],"relativePath":"fe/ai/realtime.md","filePath":"fe/ai/realtime.md"}'),e={name:"fe/ai/realtime.md"};function d(r,t,n,h,o,p){return a(),l("div",null,t[0]||(t[0]=[s(`<h1 id="实时数据传输" tabindex="-1">实时数据传输 <a class="header-anchor" href="#实时数据传输" aria-label="Permalink to &quot;实时数据传输&quot;">​</a></h1><h2 id="sse" tabindex="-1">SSE <a class="header-anchor" href="#sse" aria-label="Permalink to &quot;SSE&quot;">​</a></h2><ol><li><p>定义</p><p>SSE 是一种基于 HTTP 协议的 单向通信协议，允许服务器以事件流（Event Stream）的形式实时向客户端推送数据，而无需客户端主动请求。它是 HTML5 规范的一部分，主要面向浏览器端应用。</p></li><li><p>工作原理</p></li></ol><ul><li>单向通信：数据只能从服务器流向客户端。</li><li>事件驱动：服务器可以发送包含事件类型、数据等信息的消息，客户端通过监听事件进行处理。</li><li>持久连接：客户端与服务器建立一个持久的 HTTP 连接，服务器在有新事件时立即推送数据。</li><li>自动重连：如果连接中断，客户端会自动尝试重新连接。</li></ul><ol start="3"><li>数据格式</li></ol><p>SSE 使用特定的文本格式，每条事件消息包含以下字段：</p><ul><li>data: 事件数据（必须）。</li><li>event: 事件类型（可选）。</li><li>id: 事件标识符（可选，用于重连后恢复状态）。</li><li>retry: 重连间隔时间（可选）</li></ul><div class="language-JSON vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">JSON</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">event: message</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stock&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;100.5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;news&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Breaking News!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="4"><li>优点</li></ol><ul><li>实时性：适合需要服务器主动推送的场景（如股票价格、社交媒体动态）。</li><li>简单易实现：基于 HTTP 协议，客户端通过 EventSource API 可轻松实现。</li><li>轻量级：相比 WebSocket，SSE 的连接和维护消耗更少资源。</li><li>自动重连：客户端支持自动重连机制。</li></ul><ol start="5"><li>缺点</li></ol><ul><li>单向通信：客户端无法通过 SSE 向服务器发送消息，需通过其他方式（如 HTTP 请求）。</li><li>浏览器限制：浏览器对 SSE 连接数有限制（通常每个域名最多 6 个）。</li><li>不支持二进制数据：仅适合文本数据传输。</li></ul><ol start="6"><li>适用场景</li></ol><ul><li>实时通知系统（如邮件提醒、消息推送）。</li><li>多人协作应用（如文档协同编辑）。</li><li>游戏排行榜更新。</li><li>任何需要服务器主动推送事件的场景。</li></ul><h2 id="streamable-http" tabindex="-1">Streamable HTTP <a class="header-anchor" href="#streamable-http" aria-label="Permalink to &quot;Streamable HTTP&quot;">​</a></h2><ol><li>定义</li></ol><p>Streamable HTTP 是一种基于 HTTP 协议的 流式传输机制，允许服务器在生成响应的过程中逐步发送数据，而无需等待整个数据集准备完成。它不是专门定义的协议，而是对 HTTP 的灵活使用。</p><ol start="2"><li>工作原理</li></ol><ul><li>流式传输：服务器在数据生成时逐步发送，客户端可以逐块接收和处理数据。</li><li>灵活的数据格式：数据格式由应用层定义，可以是文本、二进制或自定义格式。</li><li>无强制持久连接：可以使用持久连接或一次性连接，具体取决于应用场景。</li><li>双向通信：理论上支持双向通信（需额外实现）。</li></ul><ol start="3"><li>数据格式</li></ol><p>Streamable HTTP 没有固定格式，数据可以是任意格式（如 JSON、二进制流、分块编码等）。例如：</p><ul><li>分块传输编码（Chunked Transfer Encoding）：服务器分块发送数据，客户端逐步接收。</li><li>自定义协议：应用层定义数据分隔符或消息头（如 Content-Type 指定数据类型）。</li></ul><ol start="4"><li>优点</li></ol><ul><li>高效处理大数据：适合传输大文件或连续数据流（如视频、音频）。</li><li>实时性：数据在生成时即可传输，减少延迟。</li><li>灵活性：支持多种数据格式（文本、二进制），适合复杂场景。</li><li>兼容性强：基于 HTTP，可与现有基础设施（如 CDN、代理服务器）无缝集成。</li></ul><ol start="5"><li>缺点</li></ol><ul><li>复杂性高：需要手动管理数据流的顺序、完整性及连接状态。</li><li>资源消耗：长时间保持连接可能消耗更多服务器资源。</li><li>无内置事件机制：需要应用层实现事件处理逻辑（如消息解析）。</li></ul><ol start="6"><li>适用场景</li></ol><ul><li>大文件下载（如视频、软件更新）。</li><li>实时流媒体（如在线视频直播、音频流）。</li><li>大数据分析结果推送。</li><li>AI 模型通信（如 MCP 协议中的流式数据传输）。</li></ul><table tabindex="0"><thead><tr><th>特性</th><th>SSE</th><th>Streamable HTTP</th></tr></thead><tbody><tr><td>通信方向</td><td>单向（服务器 → 客户端）</td><td>双向（取决于实现）</td></tr><tr><td>事件机制</td><td>内置事件系统</td><td>无内置事件系统</td></tr><tr><td>连接保持</td><td>持久连接</td><td>可持久或断开连接</td></tr><tr><td>数据格式</td><td>特定文本格式（data、event 等）</td><td>灵活，可自定义（文本、二进制等）</td></tr><tr><td>自动重连</td><td>内置自动重连机制</td><td>需应用层实现</td></tr><tr><td>浏览器支持</td><td>现代浏览器（除 IE/Edge）</td><td>所有支持 HTTP 的客户端</td></tr><tr><td>资源消耗</td><td>较低</td><td>可能较高（需管理连接和流）</td></tr><tr><td>适用场景</td><td>实时事件推送（如股票价格）</td><td>大数据流传输（如视频、AI 模型通信）</td></tr></tbody></table><p><strong>在 MCP 协议中中的应用</strong></p><p>Model Context Protocol (MCP) 是一种用于标准化 AI 模型与应用程序通信的开放协议。在 MCP 中，Streamable HTTP 被用作传输层，支持以下特性：</p><ul><li>流式传输：允许 AI 模型逐步返回结果（如大语言模型的生成过程）。</li><li>统一接口：通过 /message 端点处理所有请求和流式响应，无需单独的 /sse 端点。</li><li>无状态服务器：Streamable HTTP 支持无状态模式，便于部署高可用服务。</li><li>兼容性：基于 HTTP，可与现有基础设施（如负载均衡器、CDN）无缝集成。</li></ul><table tabindex="0"><thead><tr><th>维度</th><th>SSE</th><th>Streamable HTTP</th></tr></thead><tbody><tr><td>演进趋势</td><td>逐步被替代（如 MCP 协议已弃用 SSE）</td><td>新兴标准（MCP、云服务的推荐方案）</td></tr><tr><td>设计定位</td><td>轻量级实时通知</td><td>高性能流式处理 + 双向交互</td></tr><tr><td>典型用例</td><td>新闻推送、进度条更新</td><td>AI 多轮对话、大模型流式输出</td></tr></tbody></table>`,33)]))}const u=i(e,[["render",d]]);export{E as __pageData,u as default};
